import math
base = {"cluster": 0.19, "complex": 0.05, "edge": 0.15, "face": 0.19, "scratch": 0.42}
now  = {"cluster": 0.12, "complex": 0.04, "edge": 0.30, "face": 0.16, "scratch": 0.38}
psi = sum((now[k] - base[k]) * math.log(now[k] / base[k]) for k in base)
print("PSI", round(psi, 3))
# PSI 0.148
